const fs = require('node:fs');
const path = require('node:path');
const {test, expect} = require('playwright/test');

// Generated by EditingUrlBrowserFixtureTest during the current Maven test/package run.
const generated = fs.readFileSync(path.resolve(__dirname,
    '../../simplypages/target/editing-url-browser-fixture.html'), 'utf8');

for (const width of [390, 1440]) {
    test(`actual editing URLs preserve opaque IDs through browser normalization at ${width}px`, async ({page}) => {
        await page.setViewportSize({width, height: 900});
        await page.route('**/editing-url-fixture', route => route.fulfill({contentType: 'text/html', body:
            `<!doctype html><html><head><meta charset="UTF-8"></head><body>${generated}</body></html>`}));
        await page.goto('/editing-url-fixture');
        const samples = await page.locator('.url-sample').evaluateAll(elements => elements.map(sample => {
            const raw = sample.getAttribute('data-raw-id');
            const urls = [...sample.querySelectorAll('[hx-get], [hx-post], [hx-delete]')].map(button => {
                const value = button.getAttribute('hx-get') || button.getAttribute('hx-post') || button.getAttribute('hx-delete');
                const url = new URL(value, location.href);
                return {value, pathname: url.pathname, segments: url.pathname.split('/'),
                    id: url.searchParams.get('id'), position: url.searchParams.get('position'), hash: url.hash};
            });
            return {raw, urls};
        }));
        expect(samples).toHaveLength(6);
        for (const {raw, urls} of samples) {
            const encoded = encodeURIComponent(raw).replace(/[!'()*]/g,
                character => `%${character.charCodeAt(0).toString(16).toUpperCase()}`);
            expect(urls).toHaveLength(7); // insertion, module edit/delete/add, child edit/delete, complete save
            for (const url of urls) {
                if (url.pathname === '/save') continue;
                if (url.position !== null) {
                    expect(url.pathname).toBe(`/api/pages/${encoded}/rows/insert`);
                    expect(url.position).toBe('0');
                } else if (url.pathname.startsWith('/api/pages/')) {
                    expect(url.pathname).toBe(`/api/pages/${encoded}/rows/${encoded}/add-module-form`);
                } else if (url.pathname.startsWith('/child')) {
                    expect(url.segments).toHaveLength(3);
                    expect(url.segments[2]).toBe(encoded);
                    expect(url.id).toBe(raw);
                    expect(url.hash).toBe('#fragment?');
                } else {
                    expect(url.segments).toHaveLength(5);
                    expect(url.segments.slice(2)).toEqual([encoded, encoded, encoded]);
                    expect(url.id).toBe(raw);
                    expect(url.hash).toBe('#fragment?');
                }
                expect(url.value).not.toContain(' ');
                expect(url.value).not.toContain('\\');
            }
        }
        const rejected = page.locator('.rejected-id');
        await expect(rejected).toHaveCount(2);
        expect(await rejected.evaluateAll(elements => elements.map(element => element.getAttribute('data-raw-id'))))
            .toEqual(['.', '..']);
        await expect(rejected.locator('[hx-get], [hx-post], [hx-delete]')).toHaveCount(0);
        // Browser handling itself explains why encoding exact dots would not preserve them.
        expect(await page.evaluate(() => new URL('/root/%2E%2E/tail', location.href).pathname)).toBe('/tail');
    });

    test(`template classification survives actual browser URL preprocessing at ${width}px`, async ({page}) => {
        await page.setViewportSize({width, height: 900});
        await page.route('**/editing-url-fixture', route => route.fulfill({contentType: 'text/html', body:
            `<!doctype html><html><head><meta charset="UTF-8"></head><body>${generated}</body></html>`}));
        await page.goto('/editing-url-fixture');
        const rejected = page.locator('.rejected-authority-template');
        await expect(rejected).toHaveCount(52);
        await expect(rejected.locator('[hx-get], [hx-post], [hx-delete]')).toHaveCount(0);
        const destinations = await rejected.evaluateAll(elements => elements.map(element => {
            const candidate = atob(element.getAttribute('data-candidate-base64'));
            const url = new URL(candidate, location.href);
            return {candidate, hostname: url.hostname, pathname: url.pathname};
        }));
        // All rejected Java setter cases would place this unreserved opaque ID in the
        // authority. The old parser missed this for scheme/slash and ignored-control forms.
        for (const destination of destinations) {
            expect(destination.hostname, JSON.stringify(destination.candidate)).toBe('destination.example');
            expect(destination.pathname).toBe('/edit');
        }
        const accepted = await page.locator('.supported-template').evaluateAll(elements => elements.map(element => {
            const button = element.querySelector('[hx-post]');
            const value = button.getAttribute('hx-post');
            const url = new URL(value, location.href);
            return {raw: element.getAttribute('data-raw-id'), expectedHost: element.getAttribute('data-expected-host'),
                expectedPath: element.getAttribute('data-expected-path'), value, hostname: url.hostname,
                pathname: url.pathname, id: url.searchParams.get('id'), hash: url.hash};
        }));
        expect(accepted).toHaveLength(32);
        for (const sample of accepted) {
            const encoded = encodeURIComponent(sample.raw).replace(/[!'()*]/g,
                character => `%${character.charCodeAt(0).toString(16).toUpperCase()}`);
            expect(sample.hostname, sample.value).toBe(sample.expectedHost);
            expect(sample.pathname, sample.value).toBe(sample.expectedPath.replace('{id}', encoded));
            expect(sample.id, sample.value).toBe(sample.raw);
            expect(sample.hash).toBe('#F?');
        }
    });
}
